edits.after:
if (c->sb.clean) {
	clean = bch2_read_superblock_clean(c);
	ret = PTR_ERR_OR_ZERO(clean);
	if (ret)
		goto err;
}

if (clean) {
	bch_info(c, "recovering from clean shutdown, journal seq %llu",
		 le64_to_cpu(clean->journal_seq));
} else {
	bch_info(c, "recovering from unclean shutdown");
}

